/* Card set: Ships & Boats (built from the approved merged roster.csv by the Ships build).
   384 cards: Tall Ships & Historic Sailing, Ocean Liners, Wrecks & Mysteries,
   Riverboats/Ferries/Working Boats, Explorers & Record Setters, Weird & Wonderful.
   Art: real photography and period art, eyeball-verified per image. The remaining
   cards live in ships-additions.js, which must stay directly after 'ships.js'
   in sets/manifest.js. */
CardSets.register({"id":"ships","name":"Ships & Boats","code":"SHIP","description":"384 cards of the vessels that carried the world — tall ships and ocean liners, famous wrecks and mysteries, riverboats and working boats, explorers, record-breakers and the strangest craft afloat.","theme":{"primary":"#175d7a","secondary":"#0d2f42","artBackground":"#e8f1f2","artFit":"cover"},"pack":{"name":"Ships & Boats Pack","emblem":"🚢","skin":"ships","slots":[{"count":5,"label":"Common","odds":{"common":100}},{"count":2,"label":"Uncommon","odds":{"uncommon":100}},{"count":1,"label":"Wild card","odds":{"common":55,"uncommon":30,"rare":12,"epic":3}},{"count":1,"label":"Rare or better (guaranteed)","odds":{"rare":81.8,"epic":14,"legendary":4,"chase":0.2}}]},"cards":[{"name":"Cutty Sark","rarity":"chase","id":"cutty-sark","subtitle":"Clipper","details":"One of the last tea clippers built, launched in 1869 for the China trade; preserved in a dry dock at Greenwich, London.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Northeast_View_of_the_Cutty_Sark_in_Greenwich.jpg?width=1024"},{"name":"HMS Victory","rarity":"chase","id":"hms-victory","subtitle":"Ship of the Line","details":"Launched in 1765, Nelson's flagship at Trafalgar in 1805; the oldest naval vessel still in commission, preserved at Portsmouth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMSVictoryPortsmouthEngland_%28version_2%29.jpg?width=1024"},{"name":"Vasa","rarity":"chase","id":"vasa","subtitle":"Galleon","details":"Swedish warship that sank on her maiden voyage in Stockholm harbour in 1628; raised in 1961 nearly intact for her own museum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Vasa_from_the_Bow.jpg?width=1024"},{"name":"Mayflower","rarity":"chase","id":"mayflower","subtitle":"Tall Ship","details":"The merchant ship that carried the Pilgrims from England to New England in 1620, anchoring off Cape Cod that November.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Copyrighted_and_Published_by_A_S_Burbank%2C_The_Mayflower_at_Sea_%28NBY_21340%29.jpg?width=1024"},{"name":"Santa María","rarity":"legendary","id":"santa-maria","subtitle":"Carrack","details":"Columbus's flagship of 1492, the largest of his three ships; she grounded on a reef off Hispaniola on Christmas Day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kolumbus-Santa-Maria.jpg?width=1024"},{"name":"Golden Hind","rarity":"legendary","id":"golden-hind","subtitle":"Galleon","details":"Drake's galleon, renamed from Pelican mid-voyage; the only ship of his fleet to finish the 1577-1580 circumnavigation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Francis-drake-galleon-southwark-london-uk.jpg?width=1024"},{"name":"Mary Rose","rarity":"legendary","id":"mary-rose","subtitle":"Carrack","details":"Henry VIII's carrack flagship, sunk in the Solent in 1545; her hull was raised in 1982 and preserved at Portsmouth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AnthonyRoll-2_Mary_Rose.jpg?width=1024"},{"name":"HMS Bounty","rarity":"legendary","id":"hms-bounty","subtitle":"Tall Ship","details":"The merchant ship bought by the Royal Navy in 1787 for a breadfruit voyage, seized by Fletcher Christian's mutineers in 1789.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMS_BOUNTY_II_with_Full_Sails.jpg?width=1024"},{"name":"Charles W. Morgan","rarity":"legendary","id":"charles-w-morgan","subtitle":"Whaler","details":"Launched in 1841, the last surviving wooden whaleship; she worked 37 voyages over 80 years and rests at Mystic Seaport.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Charles_W_Morgan.jpg?width=1024"},{"name":"Thermopylae","rarity":"epic","id":"thermopylae","subtitle":"Clipper","details":"Aberdeen-built clipper launched in 1868, famed for her ocean duels with Cutty Sark on the tea and wool trades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thermopylaeclipperpainting.jpg?width=1024"},{"name":"Flying Cloud","rarity":"epic","id":"flying-cloud","subtitle":"Clipper","details":"The 1851 McKay clipper whose 89-day New York to San Francisco record of 1854 stood for more than 135 years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flying_Cloud_by_Jacobsen.webp?width=1024"},{"name":"Great Republic","rarity":"epic","id":"great-republic","subtitle":"Clipper","details":"Launched in 1853, at 4,555 tons the largest clipper ship ever built; fire forced her rebuilding before her first voyage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/GreatRepublic%20ca1853%20byButtersworth%20PEM.jpg?width=1024"},{"name":"Marco Polo","rarity":"epic","id":"marco-polo","subtitle":"Clipper","details":"The 1851 New Brunswick clipper that first made the Liverpool-Australia round trip in under six months, carrying emigrants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/StateLibQld%201%20112300%20Marco%20Polo%20%28ship%29.jpg?width=1024"},{"name":"Amerigo Vespucci","rarity":"epic","id":"amerigo-vespucci","subtitle":"Tall Ship","details":"Italian full-rigged training ship launched in 1931, a steel-hulled namesake of the Florentine explorer Amerigo Vespucci.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amerigo%20Vespucci%2C%20Portofino%2006.jpg?width=1024"},{"name":"Kruzenshtern","rarity":"epic","id":"kruzenshtern","subtitle":"Barque","details":"Built in 1926 as Padua, a four-masted Flying P-Line barque; renamed for explorer Adam von Krusenstern after 1946.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%9A%D1%80%D1%83%D0%B7%D0%B5%D0%BD%D1%88%D1%82%D0%B5%D1%80%D0%BD_Radich.JPG?width=1024"},{"name":"Sedov","rarity":"epic","id":"sedov","subtitle":"Barque","details":"Launched in 1921 as Magdalene Vinnen II, a four-masted steel barque among the largest traditional sailing ships built.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sedov_%28ship%2C_1921%29%2C_S%C3%A8te%2C_H%C3%A9rault_07.jpg?width=1024"},{"name":"Preussen","rarity":"epic","id":"preussen","subtitle":"Windjammer","details":"The only five-masted full-rigged ship ever built, launched in 1902 to haul nitrate around Cape Horn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Preussen_-_StateLibQld_70_73320.jpg?width=1024"},{"name":"Niña","rarity":"rare","id":"nina","subtitle":"Caravel","details":"The smallest of Columbus's 1492 fleet and his favourite, a nimble caravel that survived a hurricane on the way home.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gustav_Adolf_Closs_-_Die_Schiffe_des_Columbus_-_1892.jpg?width=1024"},{"name":"Pinta","rarity":"rare","id":"pinta","subtitle":"Caravel","details":"The fastest of Columbus's three ships in 1492; her lookout Rodrigo de Triana made the fleet's first sighting of land.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LaPinta.jpg?width=1024"},{"name":"Duyfken","rarity":"rare","id":"duyfken","subtitle":"Tall Ship","details":"The little Dutch ship whose 1606 voyage under Willem Janszoon made the first recorded European landing in Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Duyfken_replica%2C_Swan_River.jpg?width=1024"},{"name":"Batavia","rarity":"rare","id":"batavia","subtitle":"East Indiaman","details":"Dutch East Indiaman built in 1628 and wrecked on the Abrolhos Islands in 1629; a mutiny among survivors followed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/De_BATAVIA_voor_de_film_onderweg_als_de_NIEUW_HOORN_%2802%29.jpg?width=1024"},{"name":"Kronan","rarity":"rare","id":"kronan","subtitle":"Ship of the Line","details":"Swedish flagship and among the largest warships of her age; she capsized and exploded in battle off Öland in 1676.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stora_Kronan.jpeg?width=1024"},{"name":"Soleil Royal","rarity":"rare","id":"soleil-royal","subtitle":"Ship of the Line","details":"Louis XIV's lavishly decorated 104-gun flagship, destroyed by fireships in 1692 after the battles of Barfleur and La Hogue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Destruction_of_the_Soleil_Royal_at_the_Battle_of_La_Hogue%2C_23_May_1692_RMG_BHC0338_%28cropped%29.tiff?width=1024"},{"name":"Santísima Trinidad","rarity":"rare","id":"santisima-trinidad","subtitle":"Ship of the Line","details":"The largest warship of her era, a Spanish first-rate carrying guns on four decks; captured in ruins at Trafalgar in 1805.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Santissima_Trinidad_RMG_A5090.tiff?width=800"},{"name":"Götheborg","rarity":"rare","id":"gotheborg","subtitle":"East Indiaman","details":"Replica of the Swedish East Indiaman that sank off Gothenburg in 1745; the replica retraced her China route in 2005-2007.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%B6theborg_%28ship%29_in_Stockholm_2021_01.jpg?width=1024"},{"name":"Gokstad Ship","rarity":"rare","id":"gokstad-ship","subtitle":"Longship","details":"A Viking longship buried in a mound at Gokstad around 890 and dug up in 1880, now displayed in Oslo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gokstadskipet1.jpg?width=1024"},{"name":"Oseberg Ship","rarity":"rare","id":"oseberg-ship","subtitle":"Longship","details":"The most richly carved Viking ship burial, interred in 834 and excavated near Tønsberg in 1904.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Osebergskipet_2016.jpg?width=1024"},{"name":"Balclutha","rarity":"rare","id":"balclutha","subtitle":"Windjammer","details":"Glasgow-built in 1886, a steel-hulled square-rigger that rounded Cape Horn 17 times and ended her days as a museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Balclutha_2016.jpg?width=1024"},{"name":"Falls of Clyde","rarity":"rare","id":"falls-of-clyde","subtitle":"Windjammer","details":"Launched in 1878, a four-masted iron ship built for the Hawaii trade; she long survived as the last sail-driven oil tanker.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hull_of_wood%2C_heart_of_steel_%282620978622%29.jpg?width=1024"},{"name":"Sea Cloud","rarity":"rare","id":"sea-cloud","subtitle":"Barque","details":"Built in 1931 as the private yacht Hussar, a four-masted barque with a gilded main cabin from her floating-palace days.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sea_Cloud_I.jpg?width=1024"},{"name":"L'Hermione","rarity":"rare","id":"lhermione","subtitle":"Frigate","details":"Replica, completed in 2014, of the 1779 frigate that carried Lafayette to join the American Revolution; she crossed in 2015.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Premiere_sortie_de_l%27Hermione_dsc3310E.jpg?width=1024"},{"name":"Dar Młodzieży","rarity":"uncommon","id":"dar-mlodziezy","subtitle":"Tall Ship","details":"Polish full-rigged training ship launched in 1981, her name meaning Gift of the Youth; prototype of a class of six.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dar_Mlodziezy2007.jpg?width=1024"},{"name":"Christian Radich","rarity":"uncommon","id":"christian-radich","subtitle":"Tall Ship","details":"Norwegian full-rigged training ship delivered in 1937, star of the 1958 film Windjammer and a tall ships race regular.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tall_ship_Christian_Radich_under_sail.jpg?width=1024"},{"name":"Statsraad Lehmkuhl","rarity":"uncommon","id":"statsraad-lehmkuhl","subtitle":"Barque","details":"Launched in 1914 as Germany's Grossherzog Friedrich August, a three-masted barque that became Bergen's beloved training ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Statsraad_Lehmkuhl_%2814%29.jpg?width=1024"},{"name":"Gorch Fock","rarity":"uncommon","id":"gorch-fock","subtitle":"Barque","details":"German training barque launched in 1958, named for the seafaring poet who died at Jutland in 1916.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gorch_Fock_unter_Segeln_Kieler_Foerde_2006.jpg?width=1024"},{"name":"Juan Sebastián de Elcano","rarity":"uncommon","id":"juan-sebastian-de-elcano","subtitle":"Schooner","details":"Spanish four-masted training schooner launched in 1927, named for the Basque sailor who completed Magellan's voyage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Juan%20Sebastian%20de%20Elcano%20at%20Pensacola.jpg?width=1024"},{"name":"Esmeralda","rarity":"uncommon","id":"esmeralda","subtitle":"Schooner","details":"Chilean four-masted training schooner of the 1950s, among the tallest sailing ships ever put to sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Esmeralda_BE43.jpg?width=1024"},{"name":"Libertad","rarity":"uncommon","id":"libertad","subtitle":"Tall Ship","details":"Argentine full-rigged training ship launched in 1956, holder of North Atlantic speed records for sail training ships.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Q2ARALibertad.jpg?width=1024"},{"name":"Cisne Branco","rarity":"uncommon","id":"cisne-branco","subtitle":"Clipper","details":"Brazilian full-rigged training ship launched in 1999, her name meaning White Swan after the navy's anthem.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CisneBranco07.jpg?width=1024"},{"name":"Cuauhtémoc","rarity":"uncommon","id":"cuauhtemoc","subtitle":"Barque","details":"Mexican training barque launched in 1982, named for the last Aztec emperor and a fixture of tall ship festivals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cuauht%C3%A9moc_%287866888592%29.jpg?width=1024"},{"name":"Nippon Maru","rarity":"uncommon","id":"nippon-maru","subtitle":"Barque","details":"Japanese training barque launched at Kobe in 1930, preserved at Yokohama where she is nicknamed the Pacific Swan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nihonmaru_1.jpg?width=1024"},{"name":"Kaiwo Maru","rarity":"uncommon","id":"kaiwo-maru","subtitle":"Barque","details":"Japanese training barque launched at Kobe in 1930 alongside sister Nippon Maru; preserved as a museum ship at Toyama.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kaiwo_Maru%2C_Kaiwomaru_Park_20080721115059.jpg?width=1024"},{"name":"Sørlandet","rarity":"uncommon","id":"sorlandet","subtitle":"Tall Ship","details":"Norwegian full-rigged training ship launched in 1927, named for the South Coast region around her home port Kristiansand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B8rlandet_in_Oslo_7jun2005.jpg?width=1024"},{"name":"Europa","rarity":"uncommon","id":"europa","subtitle":"Barque","details":"Built in 1911 as the lightship Senator Brockes and rerigged as a barque; a Dutch ocean wanderer famed for Antarctic voyages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SV%20Europa%20barque%202007-07.jpg?width=1024"},{"name":"Picton Castle","rarity":"uncommon","id":"picton-castle","subtitle":"Barque","details":"A Swansea-built trawler of 1928 rerigged as a barque, famed for sail-training world voyages out of Lunenburg, Nova Scotia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PictonCastle-AnchoredOffCarriacou-March14-09.jpg?width=1024"},{"name":"Kalmar Nyckel","rarity":"uncommon","id":"kalmar-nyckel","subtitle":"Tall Ship","details":"Replica of the Dutch-built pinnace that carried Swedish settlers to Delaware in 1638, founding New Sweden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kalmar_Nyckel_by_Jacob_H%C3%A4gg_cropped.jpg?width=1024"},{"name":"HMS Surprise","rarity":"uncommon","id":"hms-surprise","subtitle":"Frigate","details":"The frigate replica launched in 1970 as HMS Rose, renamed Surprise for her starring role in Master and Commander.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMS-Surprise-overall.jpg?width=1024"},{"name":"Bluenose II","rarity":"uncommon","id":"bluenose-ii","subtitle":"Schooner","details":"Replica of the undefeated 1921 racing schooner Bluenose, built in 1963 at the same Lunenburg yard as the original.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2022-08-04_01_BLUENOSE_II_-_IMO_5419086_%E2%80%93_off_Blue_Rocks_NS_CAN.jpg?width=1024"},{"name":"James Craig","rarity":"uncommon","id":"james-craig","subtitle":"Barque","details":"An 1874 iron barque built as Clan Macleod, restored by Sydney volunteers and returned to regular sailing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/James_Craig.jpg?width=1024"},{"name":"Elissa","rarity":"uncommon","id":"elissa","subtitle":"Barque","details":"Iron barque launched in 1877 and preserved at Galveston; one of the oldest tall ships still taken to sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elissa-ship.jpg?width=1024"},{"name":"Peking","rarity":"uncommon","id":"peking","subtitle":"Barque","details":"A four-masted Flying P-Line barque of 1911, brought home to Hamburg in 2020 after decades as a New York museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schleswig-Holstein%2C_Wewelsfleth%2C_Peters_Werft_und_Peking_NIK_0987.jpg?width=1024"},{"name":"Pommern","rarity":"uncommon","id":"pommern","subtitle":"Barque","details":"A 1903 Flying P-Line barque preserved at Mariehamn, kept close to her working cargo-ship configuration.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pommern%2C_%C3%85land_Maritime_Museum%2C_2019_%2801%29.jpg?width=1024"},{"name":"Passat","rarity":"uncommon","id":"passat","subtitle":"Barque","details":"A 1911 Flying P-Line barque saved from scrap by Lübeck, moored at Travemünde as a museum and youth hostel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flying_P-Liner_Passat_ship_in_Travem%C3%BCnde.jpg?width=1024"},{"name":"Susan Constant","rarity":"uncommon","id":"susan-constant","subtitle":"Tall Ship","details":"The largest of the three ships that founded Jamestown in 1607; her replica rides at anchor at Jamestown Settlement.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JamestownShips.jpg?width=1024"},{"name":"Moshulu","rarity":"common","id":"moshulu","subtitle":"Barque","details":"A 1904 four-masted barque, winner of the last great grain race from Australia in 1939; later a Philadelphia restaurant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moshulu_at_Penn%27s_Landing.jpg?width=1024"},{"name":"Lawhill","rarity":"common","id":"lawhill","subtitle":"Barque","details":"A steel four-masted barque of 1892 named for the Dundee hill above her builders' yard, a veteran of the grain trade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lawhill_SLV_AllanGreen.jpg?width=1024"},{"name":"Herzogin Cecilie","rarity":"common","id":"herzogin-cecilie","subtitle":"Barque","details":"A 1902 German barque named for a crown princess, famed for fast grain-race passages under Finnish ownership; wrecked in 1936.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Herzogin_Cecilie_SLV_AllenGren.jpg?width=1024"},{"name":"Royal Clipper","rarity":"common","id":"royal-clipper","subtitle":"Tall Ship","details":"A five-masted full-rigged cruise ship launched in 2000, modelled on Preussen and the largest of her kind at launch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Royal-clipper.jpg?width=1024"},{"name":"Star Flyer","rarity":"common","id":"star-flyer","subtitle":"Clipper","details":"A four-masted, clipper-bowed cruise ship launched in 1991, carrying passengers under acres of sail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Star_Flyer_%281%29.JPG?width=1024"},{"name":"BAP Unión","rarity":"common","id":"bap-union","subtitle":"Barque","details":"Peruvian four-masted training barque launched in 2014, the largest sail training ship in Latin America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BAP%20UNION%20BEV161%20A%20Peruvian%20Navy%20sail%20training%20four-masted%20barque.jpg?width=1024"},{"name":"Gloria","rarity":"common","id":"gloria","subtitle":"Barque","details":"Colombian three-masted training barque launched in 1968, the first of South America's modern sail training ships.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Buque_Insignia_ARC_Gloria.JPG?width=1024"},{"name":"Star of Bengal","rarity":"common","id":"star-of-bengal","subtitle":"Barque","details":"An iron barque of 1874, wrecked off Coronation Island, Alaska, in 1908 with a cargo of cannery workers and supplies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/StateLibQld_1_172019_Star_of_Bengal_%28ship%29.jpg?width=1024"},{"name":"Lady Washington","rarity":"common","id":"lady-washington","subtitle":"Brig","details":"Replica, launched in 1989, of the 1780s brig that opened American maritime trade with the Pacific Northwest and Japan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lady_Washington_Commencement_Bay2.jpg?width=800"},{"name":"Schulschiff Deutschland","rarity":"common","id":"schulschiff-deutschland","subtitle":"Tall Ship","details":"The last full-rigged training ship built for Germany, launched in 1927 and preserved as a museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/150Schulschiff_Deutschland2.jpg?width=1024"},{"name":"Rickmer Rickmers","rarity":"common","id":"rickmer-rickmers","subtitle":"Barque","details":"An 1896 barque rescued from the scrapyard and moored at Hamburg, her green hull a harbour landmark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rickmer_Rickmers_nach_Restaurierung_09-2016_%282%29.jpg?width=1024"},{"name":"Suomen Joutsen","rarity":"common","id":"suomen-joutsen","subtitle":"Tall Ship","details":"A full-rigged ship launched in 1902 as Laënnec, long a Finnish training ship and preserved at Turku.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suomen_Joutsen_1932.jpg?width=1024"},{"name":"Af Chapman","rarity":"common","id":"af-chapman","subtitle":"Tall Ship","details":"A steel full-rigged ship launched in 1888 as Dunboyne, moored at Stockholm since 1949 as a youth hostel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Af_Chapman_at_Skeppsholmen_in_Stockholm_City.jpg?width=1024"},{"name":"Sigyn","rarity":"common","id":"sigyn","subtitle":"Barque","details":"Built at Gothenburg in 1887, the last wooden barque to carry cargo across the oceans; preserved afloat at Turku.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sigyn_docked_in_Turku.jpg?width=1024"},{"name":"Viking","rarity":"common","id":"viking","subtitle":"Barque","details":"A Danish four-masted steel barque of 1906, the largest sailing ship built in the Nordic countries, moored at Gothenburg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Viking_SLV_AllanGreen_c.jpg?width=1024"},{"name":"Roald Amundsen","rarity":"common","id":"roald-amundsen","subtitle":"Brig","details":"A 1952 hull rebuilt in 1992 as a brig, sailing the Baltic with volunteer crews as a sail training ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roald_Amundsen_Kiel2007_1.jpg?width=1024"},{"name":"STS Leeuwin II","rarity":"common","id":"sts-leeuwin-ii","subtitle":"Barquentine","details":"Western Australia's three-masted barquentine, launched in 1986 for youth sail training from Fremantle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LeeuwinII.jpg?width=1024"},{"name":"SV Tenacious","rarity":"common","id":"sv-tenacious","subtitle":"Barque","details":"Launched in 2000, the largest wooden tall ship built in Britain for a century, designed for crews of mixed abilities.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sv_tenacious.jpg?width=1024"},{"name":"Spirit of New Zealand","rarity":"common","id":"spirit-of-new-zealand","subtitle":"Barquentine","details":"A three-masted barquentine launched in 1986, running youth development voyages from Auckland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spirit_of_New_Zealand_2.JPG?width=1024"},{"name":"R. Tucker Thompson","rarity":"common","id":"r-tucker-thompson","subtitle":"Schooner","details":"A gaff-rigged topsail schooner launched in 1985, run by a charitable trust for youth voyages in Northland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/R.Tucker_Thompson_Tallships_Parade_of_Sails_2005.jpg?width=1024"},{"name":"Denis Sullivan","rarity":"common","id":"denis-sullivan","subtitle":"Schooner","details":"A three-masted Great Lakes schooner launched at Milwaukee in 2000, the only replica of the lake cargo carriers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Denis_Sullivan.jpg?width=1024"},{"name":"Gazela","rarity":"common","id":"gazela","subtitle":"Barquentine","details":"A Portuguese-built fishing barquentine of 1901, preserved at Philadelphia as the port's tall ship ambassador.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gazela-lowlova.JPG?width=1024"},{"name":"Wavertree","rarity":"common","id":"wavertree","subtitle":"Tall Ship","details":"An iron-hulled ship of 1885 at New York's South Street Seaport, the largest wrought-iron sailing vessel afloat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wavertree%20%2814609919766%29.jpg?width=1024"},{"name":"Edwin Fox","rarity":"common","id":"edwin-fox","subtitle":"Barque","details":"Built in 1853, the only surviving convict transport ship, preserved in a dry dock at Picton, New Zealand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Edwin%20Fox%20Ship.jpg?width=1024"},{"name":"Friendship of Salem","rarity":"common","id":"friendship-of-salem","subtitle":"East Indiaman","details":"A replica launched in 2000 of the 1797 Salem East Indiaman Friendship, berthed at Salem Maritime National Historic Site.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Friendship_of_Salem.JPG?width=1024"},{"name":"Pride of Baltimore","rarity":"common","id":"pride-of-baltimore","subtitle":"Schooner","details":"A topsail schooner launched in 1977 evoking the swift Baltimore clippers of 1812; lost in an Atlantic squall in 1986.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pride101981.jpg?width=1024"},{"name":"Titanic","rarity":"chase","id":"titanic","subtitle":"Liner","details":"White Star liner that sank on her maiden voyage in April 1912 after striking an iceberg, with the loss of about 1,500 lives.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RMS_Titanic_3_%28cropped_to_ship%29.jpg?width=1024"},{"name":"Queen Mary","rarity":"chase","id":"queen-mary","subtitle":"Liner","details":"Cunard express liner of 1936 that duelled Normandie for the Blue Riband, carried whole divisions as a troopship, and retired to Long Beach.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queen%20Mary%20%28ship%2C%201936%29%20at%20Long%20Beach%2001.jpg?width=1024"},{"name":"Queen Mary 2","rarity":"chase","id":"queen-mary-2","subtitle":"Liner","details":"Cunard flagship launched in 2003, the longest passenger ship of her day at 345 metres and built for scheduled Atlantic crossings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Qm2_portboston_%28cropped%29.jpg?width=1024"},{"name":"SS United States","rarity":"legendary","id":"ss-united-states","subtitle":"Liner","details":"American liner of 1952 that took the Blue Riband on her maiden voyage and remains the fastest ocean liner ever built.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/StateLibQld_1_169487_United_States_%28ship%29.jpg?width=1024"},{"name":"Queen Elizabeth 2","rarity":"legendary","id":"queen-elizabeth-2","subtitle":"Liner","details":"Cunard flagship launched in 1967 that sailed over 5.8 million miles in 40 years before retiring to Dubai as a hotel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/VAE-dubai-QE_II_cropped.jpg?width=1024"},{"name":"Lusitania","rarity":"legendary","id":"lusitania","subtitle":"Liner","details":"Cunard speed queen of 1907 whose torpedoing off Ireland in May 1915 killed 1,198 people and shook neutral America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RMS_Lusitania_coming_into_port%2C_possibly_in_New_York%2C_1907-13-crop.jpg?width=1024"},{"name":"Mauretania","rarity":"legendary","id":"mauretania","subtitle":"Liner","details":"Cunard turbine liner of 1907 that held both Blue Riband records for 20 years, a speed crown no liner kept longer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mauretania_Under_Easy_Steam_off_the_Tyne.jpg?width=1024"},{"name":"Normandie","rarity":"legendary","id":"normandie","subtitle":"Liner","details":"French Line flagship of 1935, the largest and fastest liner of her era and an Art Deco icon; lost to fire in New York in 1942.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Normandie_at_sea_view.JPG?width=1024"},{"name":"Great Eastern","rarity":"legendary","id":"great-eastern","subtitle":"Liner","details":"Brunel's iron giant of 1858, six times larger than any earlier ship; too big for her age, she found glory laying Atlantic cables.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great_Eastern_1866-crop.jpg?width=1024"},{"name":"Olympic","rarity":"legendary","id":"olympic","subtitle":"Liner","details":"Lead ship of White Star's Olympic class and the only sister to live a full career, earning the wartime nickname 'Old Reliable'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Olympic_in_New_York_cropped.jpg?width=1024"},{"name":"SS France","rarity":"legendary","id":"ss-france","subtitle":"Liner","details":"French Line flagship of 1962, at 316 metres the longest passenger ship of the 20th century; she later cruised as the Norway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_France_moored_in_Le_Havre%2C_1978_%28cropped%29.jpg?width=1024"},{"name":"Queen Elizabeth","rarity":"epic","id":"queen-elizabeth","subtitle":"Liner","details":"Cunard's 83,000-ton liner of 1940, the largest passenger ship of her day; she burned as a floating university in Hong Kong in 1972.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RMS_Queen_Elizabeth_at_Southampton_1967_%283%29.jpg?width=1024"},{"name":"Aquitania","rarity":"epic","id":"aquitania","subtitle":"Liner","details":"Cunard's 'Ship Beautiful' of 1914, the only great liner to serve through both world wars in a 36-year career.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Aquitania.jpg?width=1024"},{"name":"Île de France","rarity":"epic","id":"ile-de-france","subtitle":"Liner","details":"French liner of 1927 famed for Art Deco interiors; in 1956 she stood by the sinking Andrea Doria and rescued 753 survivors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2-11-31%2C_L%27Ile_de_France_%28paquebot_fran%C3%A7ais%29_-_btv1b532497211_%28cropped%29.jpg?width=1024"},{"name":"Rex","rarity":"epic","id":"rex","subtitle":"Liner","details":"Italian Line flagship that seized the Blue Riband in 1933 with a westbound crossing of four days and thirteen hours.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Italian_liner_Rex.jpg?width=1024"},{"name":"Bremen","rarity":"epic","id":"bremen","subtitle":"Liner","details":"North German Lloyd's streamlined record-breaker of 1929, Blue Riband winner on her maiden voyage; burned at Bremerhaven in 1941.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/TS_Bremen.jpg?width=1024"},{"name":"SS Europa","rarity":"epic","id":"ss-europa","subtitle":"Liner","details":"Bremen's 1930 sister, fitted with a seaplane catapult; handed to France after the war, she sailed on as the Liberté.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bundesarchiv_Bild_102-09251%2C_Hamburg%2C_Probefahrt_der_%22Europa%22.jpg?width=1024"},{"name":"Empress of Britain","rarity":"epic","id":"empress-of-britain","subtitle":"Liner","details":"Canadian Pacific's 42,000-ton flagship of 1931 on the Quebec run; bombed and torpedoed off Ireland in October 1940.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Empress_of_Britain.png?width=1024"},{"name":"Nieuw Amsterdam","rarity":"epic","id":"nieuw-amsterdam","subtitle":"Liner","details":"Holland America's flagship of 1938, the largest Dutch liner of her day and a beloved 'ship of peace' on the Rotterdam–New York run.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vertrek_Nieuw_Amsterdam_uit_Hoek_van_Holland%2C_Bestanddeelnr_903-4077.jpg?width=1024"},{"name":"Rotterdam","rarity":"epic","id":"rotterdam","subtitle":"Liner","details":"Holland America's 'Grande Dame' of 1959, last of the great Dutch state liners; preserved in her home port as a hotel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/De_SS_Rotterdam.jpeg?width=1024"},{"name":"Canberra","rarity":"rare","id":"canberra","subtitle":"Liner","details":"P&O's sleek 1961 Australia liner with her engines aft; in 1982 she carried troops to the Falklands as 'the Great White Whale'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/03-Ponta_Delgada_1984.jpg?width=800"},{"name":"Oriana","rarity":"rare","id":"oriana","subtitle":"Liner","details":"The last Orient Line flagship, a 1960 liner built for the Australia run; she ended her days as a floating hotel in China.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oriana_Tonga_1985.jpg?width=1024"},{"name":"SS Australis","rarity":"rare","id":"ss-australis","subtitle":"Liner","details":"Launched in 1940 as the liner America, she became Chandris's Australis in 1965 and ferried migrants to Australia for a decade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS%20Australis%201967%20%2836950522642%29.jpg?width=1024"},{"name":"Cristoforo Colombo","rarity":"rare","id":"cristoforo-colombo","subtitle":"Liner","details":"Italian Line liner of 1954 and sister to Andrea Doria; she quietly outlived her famous twin by decades on the Atlantic run.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cristoforo_Colombo_-_IMO_5082285_-_P_Venice_1972.jpg?width=1024"},{"name":"Leonardo da Vinci","rarity":"rare","id":"leonardo-da-vinci","subtitle":"Liner","details":"Italian Line flagship of 1960, built after the loss of Andrea Doria with extra watertight subdivision for safety.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leonardo_da_Vinci_Cruise_Ship_Feb_1975_05.jpg?width=1024"},{"name":"Michelangelo","rarity":"rare","id":"michelangelo","subtitle":"Liner","details":"Italian Line's 1965 flagship, among the last liners built for the North Atlantic, with latticed aluminium funnels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Michelangelo.jpg?width=1024"},{"name":"Raffaello","rarity":"rare","id":"raffaello","subtitle":"Liner","details":"Michelangelo's 1965 sister and last Italian Line flagship on the New York run; she ended as a floating barracks in Iran.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Raffaello_%2833491820471%29.jpg?width=1024"},{"name":"Windsor Castle","rarity":"rare","id":"windsor-castle","subtitle":"Liner","details":"Union-Castle's largest Cape mail ship, a 1960 flagship on the Southampton to Cape Town run with famously traditional interiors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Windsor%20castle%20at%20las%20palmas%20%2833764477861%29.jpg?width=1024"},{"name":"Caronia","rarity":"rare","id":"caronia","subtitle":"Liner","details":"Cunard's pale-green 'Green Goddess' of 1949, a dual-purpose ship built for Atlantic crossings and one-class cruising.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RMS_Caronia_%28ca._1956%29_%28cropped%29.jpg?width=1024"},{"name":"Leviathan","rarity":"rare","id":"leviathan","subtitle":"Liner","details":"Launched as Germany's Vaterland in 1913, she became United States Lines' Leviathan, the world's largest ship through the 1920s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS%20Leviathan.jpg?width=1024"},{"name":"Berengaria","rarity":"rare","id":"berengaria","subtitle":"Liner","details":"Launched in 1912 as Hamburg America's Imperator, she spent her prime as Cunard's flagship Berengaria in the 1920s and 1930s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cunard%20Line%27s%20RMS%20Berengaria.jpg?width=1024"},{"name":"Majestic","rarity":"uncommon","id":"majestic","subtitle":"Liner","details":"Launched in 1914 as the German Bismarck and completed as White Star's Majestic, the largest ship afloat until Normandie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RMS_Majestic%2C_F._G._O._Stuart%28cropped%29.jpg?width=1024"},{"name":"Paris","rarity":"uncommon","id":"paris","subtitle":"Liner","details":"French Line flagship of 1921, famed for lavish Art Deco interiors; she caught fire and capsized at her Le Havre pier in 1939.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Photo-B002368-SS-PARIS-CIE-GENERALE-TRANSATLANTIQUE-PAQUEBOT.jpg?width=1024"},{"name":"Scythia","rarity":"uncommon","id":"scythia","subtitle":"Liner","details":"Cunard liner of 1921 whose 36-year career made her the line's longest-serving ship until Queen Elizabeth 2.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_RMS_Scythia.jpg?width=1024"},{"name":"Homeric","rarity":"uncommon","id":"homeric","subtitle":"Liner","details":"White Star's Homeric, launched in 1913 as Germany's Columbus and ceded to Britain after the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RMS%20Homeric%20old%20postcard.png?width=1024"},{"name":"Belgenland","rarity":"uncommon","id":"belgenland","subtitle":"Liner","details":"Red Star liner launched in 1914 but finished as a troopship; as Belgenland she became a star of 1920s world cruising.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A._J._Jansen_-_SS_%27Belgenland%27_of_the_Red_Star_Company_Antwerp_1931-b.jpg?width=1024"},{"name":"Stefan Batory","rarity":"uncommon","id":"stefan-batory","subtitle":"Liner","details":"Polish flagship of 1969, formerly Holland America's Maasdam, that kept Gdynia's Atlantic tradition alive into the 1980s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stefan%20Batory%20IMO%205216147%20P%20Hamburg%2007-1973.jpg?width=1024"},{"name":"Augustus","rarity":"uncommon","id":"augustus","subtitle":"Liner","details":"Italian motor liner of 1926, the largest motorship in the world when built, with four screws and a South Atlantic route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Augustus.jpg?width=1024"},{"name":"Oceanic","rarity":"uncommon","id":"oceanic","subtitle":"Liner","details":"Home Lines' flagship of 1965, famous for her magrodome pool cover; she later cruised for years as the 'Big Red Boat'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Oceanic_in_Helsinki.jpg?width=1024"},{"name":"Hanseatic","rarity":"uncommon","id":"hanseatic","subtitle":"Liner","details":"Hamburg Atlantic's flagship, launched in 1930 as Canadian Pacific's Empress of Japan; she burned at her New York pier in 1966.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Empress_of_Japan_docked_at_Vancouver_circa_1930s.jpg?width=1024"},{"name":"Northern Star","rarity":"uncommon","id":"northern-star","subtitle":"Liner","details":"Shaw Savill's one-class liner of 1962, an enlarged Southern Cross built for round-the-world voyages via South Africa and Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/StateLibQld_1_148279_Northern_Star_%28ship%29.jpg?width=1024"},{"name":"Southern Cross","rarity":"uncommon","id":"southern-cross","subtitle":"Liner","details":"Shaw Savill's revolutionary 1955 Australia liner, the first large liner with her engines and funnel placed right aft.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shaw_Savill_Liner_Southern_Cross_last_voyage_%26_cargo_vessel_Walsh_Bay_Sydney_Harbour.jpg?width=1024"},{"name":"Pendennis Castle","rarity":"uncommon","id":"pendennis-castle","subtitle":"Liner","details":"Union-Castle mail ship of 1959 that sailed the weekly Southampton to Durban 'Cape Mail' run alongside Windsor Castle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pendennis%20Castle%20ship.jpg?width=1024"},{"name":"Flandre","rarity":"uncommon","id":"flandre","subtitle":"Liner","details":"French Line's 1952 liner, whose breakdown-plagued maiden voyage made headlines; she later cruised for Costa as Carla C.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paquebot%20%22Flandre%22.jpg?width=1024"},{"name":"Shalom","rarity":"uncommon","id":"shalom","subtitle":"Liner","details":"ZIM's 1964 flagship on the Haifa to New York run and Israel's largest passenger ship, built at Saint-Nazaire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brillant_SHALOM7.jpg?width=1024"},{"name":"Veendam","rarity":"common","id":"veendam","subtitle":"Liner","details":"Holland America's turbine liner of 1922, a Rotterdam to New York stalwart alongside her sister Volendam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Veendam_1923_colour_postcard.jpg?width=1024"},{"name":"Orcades","rarity":"common","id":"orcades","subtitle":"Liner","details":"Orient Line's postwar flagship of 1948 for the Britain to Australia run, carrying thousands of migrants down under.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orcades.jpg?width=1024"},{"name":"Strathnaver","rarity":"common","id":"strathnaver","subtitle":"Liner","details":"P&O's 1931 'Beautiful White Sister', first of five white-hulled Strath-class liners built for the Australia route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/StateLibQld_1_170511_Strathnaver_%28ship%29.jpg?width=1024"},{"name":"Chusan","rarity":"common","id":"chusan","subtitle":"Liner","details":"P&O's 1950 liner for India and the Far East, named for an island off China and built to replace the lost Viceroy of India.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Chusan%2C_Singapore_1969.jpg?width=800"},{"name":"Himalaya","rarity":"common","id":"himalaya","subtitle":"Liner","details":"P&O's 1949 flagship, the line's largest and fastest ship of her day, built for the Tilbury to Sydney run.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/StateLibQld%201%20143623%20Himalaya%20%28ship%29.jpg?width=1024"},{"name":"Bergensfjord","rarity":"common","id":"bergensfjord","subtitle":"Liner","details":"Norwegian America Line's flagship of 1956 on the Oslo to New York run, an 18,739-ton liner carrying 878 passengers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aankomst_van_het_ms._Bergensfjord_in_de_Amsterdamse_haven%2C_Bestanddeelnr_910-5543.jpg?width=1024"},{"name":"Kungsholm","rarity":"common","id":"kungsholm","subtitle":"Liner","details":"Swedish American Line's elegant 1966 flagship, later beloved around the world as the cruise ship Sea Princess.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kungsholm_IMO_6512354_P_Hamburg_06-1973_%281%29.jpg?width=1024"},{"name":"Gripsholm","rarity":"common","id":"gripsholm","subtitle":"Liner","details":"Swedish American Line motor liner of 1957, built at Genoa for the Gothenburg to New York service and long cruises.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gripsholm_IMO_5136361_P_Hamburg_08-1973.jpg?width=1024"},{"name":"Sagafjord","rarity":"common","id":"sagafjord","subtitle":"Liner","details":"Norwegian America Line's luxurious 1965 liner, later a Cunard running mate to QE2 and a Saga Cruises favourite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sagafjord_IMO_6416043_P_Hamburg_1969_%283%29.JPG?width=1024"},{"name":"Empress of Canada","rarity":"common","id":"empress-of-canada","subtitle":"Liner","details":"Canadian Pacific's 1961 flagship on the Liverpool to Montreal run; in 1972 she became Mardi Gras, Carnival's first ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1971%20EMPRESS%20OF%20CANADA%20%284275531055%29.jpg?width=1024"},{"name":"Antilles","rarity":"common","id":"antilles","subtitle":"Liner","details":"French Line's white-hulled 1953 cruiser for the West Indies, near-sister to Flandre; she wrecked off Mustique in 1971.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carte_postale_du_paquebot_Antilles.jpg?width=1024"},{"name":"De Grasse","rarity":"common","id":"de-grasse","subtitle":"Liner","details":"French Line liner of 1924 that was sunk at Bordeaux in 1944, raised and rebuilt, and sailed on into the 1950s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_De_Grasse.jpg?width=1024"},{"name":"Pasteur","rarity":"common","id":"pasteur","subtitle":"Liner","details":"French liner of 1939 that sailed 41 years under four names and six flags, including a long spell as Bremen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Pasteur_Hdouay4.jpg?width=1024"},{"name":"Mary Celeste","rarity":"chase","id":"mary-celeste","subtitle":"Mystery","details":"American brigantine found drifting and completely abandoned in the Atlantic in 1872; her crew of seven was never found or explained.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mary_Celeste_as_Amazon_in_1861_%28cropped%29.jpg?width=1024"},{"name":"HMHS Britannic","rarity":"legendary","id":"hmhs-britannic","subtitle":"Wreck","details":"White Star liner of 48,943 tons, launched in 1914 as a sister of Titanic; sunk by a naval mine in the Aegean Sea in 1916 as a hospital ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMHS_Britannic.jpg?width=1024"},{"name":"Andrea Doria","rarity":"legendary","id":"andrea-doria","subtitle":"Wreck","details":"Italian liner of 29,100 tons, launched in 1951; sank off Nantucket in 1956 after colliding with the liner Stockholm in fog.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Andrea_Doria.jpg?width=1024"},{"name":"SS Edmund Fitzgerald","rarity":"legendary","id":"ss-edmund-fitzgerald","subtitle":"Wreck","details":"Great Lakes freighter of 26,000 tons, launched in 1958; lost with all 29 crew in a Lake Superior storm in November 1975.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edmund_Fitzgerald%2C_1971%2C_3_of_4_%28restored%3B_cropped%29.jpg?width=1024"},{"name":"MV Wilhelm Gustloff","rarity":"legendary","id":"mv-wilhelm-gustloff","subtitle":"Wreck","details":"German liner of 25,484 tons, launched in 1937; torpedoed in the Baltic in January 1945 during a wartime evacuation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bundesarchiv_Bild_183-H27992%2C_Lazarettschiff_%22Wilhelm_Gustloff%22_in_Danzig.jpg?width=1024"},{"name":"RMS Empress of Ireland","rarity":"legendary","id":"rms-empress-of-ireland","subtitle":"Wreck","details":"Canadian Pacific liner of 14,191 tons, launched in 1906; sank in the St. Lawrence River in 1914 after a collision in fog.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RMS_Empress_of_Ireland_Colored_Picture.png?width=800"},{"name":"Endurance","rarity":"legendary","id":"endurance","subtitle":"Wreck","details":"Shackleton's barquentine, built in Norway in 1912; crushed by Weddell Sea ice and sunk in 1915, her wreck found in 2022.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Endurance_under_full_sail_Frank_Hurley_State_Library_NSW_a090012h.jpg?width=1024"},{"name":"Costa Concordia","rarity":"epic","id":"costa-concordia","subtitle":"Wreck","details":"Cruise ship of 114,147 tons, launched in 2005; struck a reef off Giglio Island, Italy, in 2012 and was later raised and scrapped.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Costa_Concordia_%282213536356%29_%28cropped%29.jpg?width=1024"},{"name":"HMS Erebus","rarity":"epic","id":"hms-erebus","subtitle":"Mystery","details":"Royal Navy bomb vessel built in 1826; Franklin's flagship on the 1845 Northwest Passage expedition, abandoned in Arctic ice in 1848.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fran%C3%A7ois_Etienne_Musin_%281820-1888%29_-_HMS_%27Erebus%27_in_the_Ice%2C_1846_-_BHC3325_-_Royal_Museums_Greenwich.jpg?width=1024"},{"name":"HMS Terror","rarity":"epic","id":"hms-terror","subtitle":"Mystery","details":"Royal Navy bomb vessel built in 1813; lost with Franklin's 1845 expedition and found in Terror Bay in 2016, remarkably intact.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMSTerrorThrownUpByIce.jpg?width=1024"},{"name":"Essex","rarity":"epic","id":"essex","subtitle":"Wreck","details":"Nantucket whaleship of 238 tons, built in 1799; stove in and sunk by a sperm whale in the Pacific in 1820, inspiring Moby-Dick.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Essex_photo_03_b.jpg?width=1024"},{"name":"SS Central America","rarity":"epic","id":"ss-central-america","subtitle":"Wreck","details":"Side-wheel steamer built in 1853 as George Law; sank in a hurricane off the Carolinas in 1857 carrying a large shipment of gold.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SSCentralAmerica.jpg?width=1024"},{"name":"MS Estonia","rarity":"epic","id":"ms-estonia","subtitle":"Wreck","details":"Baltic ferry of 15,566 tons, launched in 1979; sank in a storm in September 1994 after her bow visor failed at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MS_Estonia.png?width=400"},{"name":"SS Eastland","rarity":"epic","id":"ss-eastland","subtitle":"Wreck","details":"Great Lakes excursion steamer launched in 1902; rolled over at her Chicago River dock in 1915 while boarding passengers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/S.S._Eastland_c.1911.jpg?width=1024"},{"name":"Sultana","rarity":"rare","id":"sultana","subtitle":"Wreck","details":"Mississippi side-wheel steamboat of 1,719 tons, built in 1863; her boilers exploded near Memphis in April 1865.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ill-fated_Sultana%2C_Helena%2C_Arkansas%2C_April_27%2C_1865.jpg?width=1024"},{"name":"Flying Dutchman","rarity":"rare","id":"flying-dutchman","subtitle":"Mystery","details":"A legend of the sea: a ghost ship said to sail forever near the Cape of Good Hope, never able to reach port.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flying_Dutchman%2C_the.jpg?width=1024"},{"name":"Le Griffon","rarity":"rare","id":"le-griffon","subtitle":"Mystery","details":"La Salle's barque built in 1679 above Niagara Falls; vanished on Lake Michigan that year, the Great Lakes' first shipwreck mystery.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le-griffon.jpg?width=1024"},{"name":"SS Republic","rarity":"rare","id":"ss-republic","subtitle":"Wreck","details":"Side-wheel steamer built in 1853 as Tennessee; sank in a hurricane off Georgia in 1865, her coin cargo recovered in 2003.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Republic_a_toda_maquina.jpg?width=1024"},{"name":"RMS Tayleur","rarity":"rare","id":"rms-tayleur","subtitle":"Wreck","details":"Iron clipper chartered by White Star, wrecked on Lambay Island in 1854 on her maiden voyage from Liverpool to Melbourne.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tayleur.jpg?width=1024"},{"name":"SS President Coolidge","rarity":"rare","id":"ss-president-coolidge","subtitle":"Wreck","details":"American liner of 21,936 tons, launched in 1931; struck mines entering Espiritu Santo harbour in 1942 and became a famed dive wreck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/S.S._President_Coolidge_at_sea%2C_1930s.jpg?width=1024"},{"name":"MS Hans Hedtoft","rarity":"rare","id":"ms-hans-hedtoft","subtitle":"Wreck","details":"Danish liner built in 1958 for Greenland service; struck an iceberg on her maiden return voyage in January 1959 and was never found.","image":"https://en.wikipedia.org/wiki/Special:FilePath/MS_Hans_Hedtoft.jpg?width=1024"},{"name":"Lady Elgin","rarity":"rare","id":"lady-elgin","subtitle":"Wreck","details":"Side-wheel passenger steamer launched in 1851; sank in Lake Michigan in 1860 after a collision with the schooner Augusta.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PS_Lady_Elgin.jpg?width=1024"},{"name":"SS Yongala","rarity":"rare","id":"ss-yongala","subtitle":"Wreck","details":"Australian passenger steamer of 3,616 tons, built in 1903; lost with all aboard in a cyclone off Townsville in 1911.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yongala_%28ship%2C_1903%29_-_SLV_H91.108-2943.jpg?width=1024"},{"name":"Baychimo","rarity":"uncommon","id":"baychimo","subtitle":"Mystery","details":"Hudson's Bay cargo steamer of 1,322 tons, built in 1914; abandoned in Arctic ice in 1931 and sighted drifting, crewless, for decades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baychimo.jpg?width=1024"},{"name":"Carroll A. Deering","rarity":"uncommon","id":"carroll-a-deering","subtitle":"Mystery","details":"Five-masted schooner built in 1919; found hard aground off Cape Hatteras in 1921 with her crew missing and boats gone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Deering2.jpg?width=1024"},{"name":"SS Waratah","rarity":"uncommon","id":"ss-waratah","subtitle":"Mystery","details":"Liner of 9,339 tons, launched in 1908; vanished without a trace off South Africa in July 1909 on her second voyage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Waratah_FL601368.jpg?width=1024"},{"name":"MV Joyita","rarity":"uncommon","id":"mv-joyita","subtitle":"Mystery","details":"American merchant vessel built in 1931; found drifting and abandoned in the Pacific in 1955, her crew never found.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MV_Joyita_1955.jpg?width=1024"},{"name":"SS Schiller","rarity":"uncommon","id":"ss-schiller","subtitle":"Wreck","details":"German transatlantic liner launched in 1873; wrecked on the Retarrier Ledges off the Isles of Scilly in May 1875.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dampfer_Schiller.jpg?width=1024"},{"name":"SS Thistlegorm","rarity":"uncommon","id":"ss-thistlegorm","subtitle":"Wreck","details":"British merchant steamer of 4,898 tons, built in 1940; sunk by aircraft in the Red Sea in 1941 and now a celebrated dive site.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thistlegorm_train_parts_minus_red_edit.jpg?width=1024"},{"name":"SS Kamloops","rarity":"uncommon","id":"ss-kamloops","subtitle":"Mystery","details":"Canadian lake freighter built in 1924; vanished in a Lake Superior storm in December 1927 and found near Isle Royale in 1977.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kamloops_ship.jpg?width=1024"},{"name":"Carl D. Bradley","rarity":"uncommon","id":"carl-d-bradley","subtitle":"Wreck","details":"Great Lakes limestone carrier of 10,637 tons, built in 1927; broke in two in a Lake Michigan storm in November 1958.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CarlDBradley_ship.jpg?width=1024"},{"name":"Princess Sophia","rarity":"uncommon","id":"princess-sophia","subtitle":"Wreck","details":"Canadian Pacific coastal liner built in 1911; wrecked on Vanderbilt Reef in Alaska in October 1918.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Princess_Sophia_%28steamship%29_%28ca_1912%29.jpg?width=1024"},{"name":"SS Valencia","rarity":"uncommon","id":"ss-valencia","subtitle":"Wreck","details":"American passenger steamer built in 1882; wrecked on the Vancouver Island coast in January 1906.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Valencia_Side.jpg?width=1024"},{"name":"SS Mohegan","rarity":"uncommon","id":"ss-mohegan","subtitle":"Wreck","details":"Passenger steamer built in 1898 as Cleopatra; wrecked on the Manacles off Cornwall in October 1898 on an early voyage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Mohegan_wrecked.jpg?width=1024"},{"name":"HMS Eurydice","rarity":"uncommon","id":"hms-eurydice","subtitle":"Wreck","details":"Royal Navy training ship built in 1843; capsized in a snow squall off the Isle of Wight in March 1878.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/William_Howard_Yorke_-_HMS_%27Eurydice%27_at_Sea_-_RMG_BHC3331.jpg?width=1024"},{"name":"MV Lyubov Orlova","rarity":"uncommon","id":"mv-lyubov-orlova","subtitle":"Mystery","details":"Yugoslav-built cruise ship launched in 1976; broke free while under tow in 2013 and drifted crewless across the North Atlantic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MV_Lyubov_Orlowa_Petermann_Island.JPG?width=1024"},{"name":"Kaz II","rarity":"common","id":"kaz-ii","subtitle":"Mystery","details":"Australian catamaran found drifting off Queensland in April 2007 with its engine running and no sign of its three crew.","image":"https://en.wikipedia.org/wiki/Special:FilePath/Kaz_townsville_forensics.jpg?width=1024"},{"name":"SS Noronic","rarity":"common","id":"ss-noronic","subtitle":"Wreck","details":"Great Lakes passenger steamer of 6,095 tons, launched in 1913; destroyed by fire at her Toronto dock in September 1949.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Noronic_at_Prescott%2C_ON_around_1939.jpg?width=1024"},{"name":"SS Richard Montgomery","rarity":"common","id":"ss-richard-montgomery","subtitle":"Wreck","details":"American Liberty ship wrecked in the Thames Estuary in 1944; her masts still mark the site off Sheerness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wreck_of_the_SS_Richard_Montgomery%2C_off_Sheerness_-_geograph.org.uk_-_4195096.jpg?width=800"},{"name":"Ryou-Un Maru","rarity":"common","id":"ryou-un-maru","subtitle":"Mystery","details":"Japanese fishing vessel torn from its moorings by the 2011 tsunami; drifted across the Pacific to Alaska in 2012.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/120404-G-IA651-038-FFV_Ryou-un_Maru.jpg?width=1024"},{"name":"Madeira","rarity":"common","id":"madeira","subtitle":"Wreck","details":"Three-masted schooner-barge built in 1900; driven onto Gold Rock, Minnesota, in a Lake Superior storm in 1905.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Madeira_4.jpg?width=1024"},{"name":"SS Clallam","rarity":"common","id":"ss-clallam","subtitle":"Wreck","details":"American passenger steamboat launched in 1903; foundered in the Strait of Juan de Fuca in January 1904.","image":"https://en.wikipedia.org/wiki/Special:FilePath/Clallam_(steamship)_.jpg?width=1024"},{"name":"SS Islander","rarity":"common","id":"ss-islander","subtitle":"Wreck","details":"Canadian Pacific coastal steamer built in 1888; struck an iceberg in Lynn Canal, Alaska, in August 1901.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Islander.jpg?width=1024"},{"name":"SS Emperor","rarity":"common","id":"ss-emperor","subtitle":"Wreck","details":"Canadian lake freighter built in 1910; wrecked on Canoe Rocks at Isle Royale in June 1947.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Emperor_in_the_St._Marys_River.jpg?width=1024"},{"name":"MV Plassy","rarity":"common","id":"mv-plassy","subtitle":"Wreck","details":"British cargo ship wrecked on Finnis Rock, Inisheer, in 1960; her rusting hull was later washed further ashore by storms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/On_the_Rocks%2C_Inisheer%2C_Aran_Islands_-2-_-_geograph.org.uk_-_637547.jpg?width=1024"},{"name":"SS Maheno","rarity":"common","id":"ss-maheno","subtitle":"Wreck","details":"Ocean liner of 5,323 tons, built in 1905; wrecked on Fraser Island, Australia, in 1935 while under tow to be scrapped.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/StateLibQld_1_256139_Maheno%2C_the_steamship_whose_hull_now_lies_rusting_on_the_beach_at_Fraser_Island%2C_ca._1905.jpg?width=1024"},{"name":"SS Sapona","rarity":"common","id":"ss-sapona","subtitle":"Wreck","details":"Concrete-hulled cargo ship built in 1919; grounded off Bimini in a 1926 hurricane and long used as a dive and film site.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sapona_Panoramic.jpg?width=1024"},{"name":"SS Palo Alto","rarity":"common","id":"ss-palo-alto","subtitle":"Wreck","details":"Concrete-hulled tanker built in 1919; beached at Aptos, California, in 1930 as an amusement pier attraction.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Palo_Alto.jpg?width=1024"},{"name":"MS World Discoverer","rarity":"common","id":"ms-world-discoverer","subtitle":"Wreck","details":"Expedition cruise ship built in 1974; struck a reef in the Solomon Islands in 2000 and rests, listing, in Roderick Bay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/WorldDiscovererInSalaverry.jpg?width=1024"},{"name":"Dimitrios","rarity":"common","id":"dimitrios","subtitle":"Wreck","details":"Greek cargo ship built in 1950 as Klintholm; beached at Valtaki, Greece, in 1981 and left to rust where she grounded.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dimitrios_Wreckage_2023.jpg?width=1024"}]});
